class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __str__(self):
        return f"({self.x}, {self.y})"

class User:
    def __init__(self, name, tags):
        self.name = name
        self.tags = tags

    def __repr__(self):
        return f"User(name={self.name}, tags={self.tags})"

class Money:
    def __init__(self, pence):
        self.pence = pence

    def __eq__(self, other):
        return isinstance(other, Money) and self.pence == other.pence

    def __hash__(self):
        return hash(self.pence)

    def __add__(self, other):
        if not isinstance(other, Money):
            raise TypeError("can only add Money to Money")
        return Money(self.pence + other.pence)


class Coupon:
    """Adds nothing, and says so from the right-hand side."""

    def __radd__(self, other):
        return other


print(Money(5) + Coupon())

tests:
assert Money(5) + Money(3) == Money(8)
assert Money(5) + Coupon() == Money(5)

try:
    Money(5) + "three"
except TypeError:
    pass
else:
    raise AssertionError("adding a string should still fail")

